const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
 ['會員違反章程可以怎麼處理','第14條'],['會員不遵守大會決議怎麼辦','三分之二'],['會員亂來違反規定怎麼處理','章程'],
 ['可以停止會員的權利嗎','沒有明文'],['會員可以被停權嗎','第16條'],['會員停權','章程'],
 ['被除名的會員可以再入會嗎','沒有規定被除名'],['會員被開除了還能再加入嗎','第37條'],['被除名後想重新入會怎麼辦','章程'],
 ['會員欠繳會費不能投票嗎','沒有規定欠繳'],['會員沒繳會費可以選理事嗎','第16條'],['欠會費的會員有投票權嗎','第33條'],
 ['退會了還能領補助嗎','不敢亂答'],['已經不是會員還能領補助嗎','08-7320415'],
 ['會員人數不夠怎麼辦','三十人以上'],['協會會員太少怎麼辦','第27條']
];
const no=['合作社社員違反章程怎麼辦','理事違反章程怎麼辦','公會會員欠會費不能投票嗎','會員欠會費可以除名嗎','會員多年沒來算退會嗎','入會費退會後可以拿回來嗎','協會補助怎麼申請','出席人數不夠怎麼辦','社區發展協會會員不夠怎麼辦','工作人員違反規定怎麼辦'];
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const txt=a?(a.title+a.summary):'';if(!txt.includes(e)||!a.direct){bad++;console.log('✗',q,a&&a.title)}});
const mine=/(會員違反法令、章程或大會決議：情節|停止會員的權利（停權）|被除名的會員可不可以再入會|欠繳會費會不會影響投票權|退會後還能不能領補助|會員人數不夠：要看)/;
no.forEach(q=>{const a=A(q);if(a&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
